@dataclass class SearchResult: text: str score: float source_file: Optional[str] section: Optional[str] domain: Optional[str] metadata: dict
def search_memory( query: str, *, k: int = 10, domains: Optional[Sequence[str]] = None, client: Optional["qdrant_db.QdrantClient"] = None, ) -> List[SearchResult]: """Search memory in Qdrant using text query.
- Validates k bounds: max(1, min(k, 50)) - Embeds query using sentence-transformers - Applies domain filters via Qdrant payload filtering - Logs duration_ms, k, domains, result_count - Returns empty list for empty queries """

router = APIRouter(prefix="/api/memory", tags=["memory"])

@router.post("/search", response_model=MemorySearchResponse)
def search_memory_endpoint(request: MemorySearchRequest) -> MemorySearchResponse:
    """Search memory and return ranked results."""
    try:
        domains = [request.source] if request.source else None
        results = memory_search.search_memory(
            request.query,
            k=request.k,
            domains=domains,
        )
    except Exception as exc:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail=f"Memory search failed: {exc}",
        ) from exc

    return MemorySearchResponse(results=[...])

@app.command("search")
def memory_search(
    query: str = typer.Argument(..., help="Natural language search query"),
    persona: Optional[str] = typer.Option(None, "--persona", help="Agent persona filter"),
    source: Optional[str] = typer.Option(None, "--source", help="Source domain filter"),
    since: Optional[str] = typer.Option(None, "--since", help="Time filter (7d or ISO-8601)"),
    k: int = typer.Option(10, "--k", help="Number of results (1-50)"),
) -> None:
    """Search memory and print ranked snippets."""
    domains = [source] if source else None
    results = search.search_memory(query, k=k, domains=domains)

    for idx, res in enumerate(results, start=1):
        typer.echo(f"[{idx}] score={res.score:.3f} domain={res.domain or '-'}")
        if res.source_file:
            typer.echo(f"    source: {res.source_file}#{res.section or ''}")
        typer.echo(f"    {res.text.strip()[:500]}")
